from taf.ul.kpi_selector.utilities.kpi_logger import log_suppression
from taf.ul.kpi_selector.operations.operation_prototype.operation_prototype import OperationPrototype


class SiteReset(OperationPrototype):
    def __init__(self, bts):
        super(SiteReset, self).__init__(bts)
        self.operation_details = {
            "Timeout": None,
            "Operation": "Site Reset",
            "Start point": "First cell down",
            "End point": "Last cell up",
            "Requirement": "-",
        }

    def get_kpi(self):
        """
        Gets kpi for site reset operation.
        :return: dictionary with timeout, requirement and operation description for site reset
        :rtype: dict
        """
        log_suppression("There was no configuration found in Gates tool for Your setup, "
                        "returning default timeout for site reset. Please, do not base Your pronto "
                        "on that value.")

        self.operation_details["Timeout"] = 800
        return self.operation_details
